parameters.jsCode:
// ---- shared chrome -------------------------------------------------------
// Inline styles only: Gmail strips <style> blocks. Coral #e35d5d is the brand
// accent from project-overview.md §25.2.
const brand = '#e35d5d';
const site = ($env.AMANTRIKA_SITE_URL || 'https://amantrika.com').replace(/\/+$/, '');
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const inr = (n) => '₹' + Number(n || 0).toLocaleString('en-IN');
const stat = (label, value) => `<div style="display:inline-block;min-width:118px;margin:0 14px 14px 0;"><div style="font-size:26px;font-weight:600;color:#1f1a19;line-height:1.1;">${value}</div><div style="font-size:12px;color:#8a7d7a;text-transform:uppercase;letter-spacing:.06em;margin-top:3px;">${label}</div></div>`;
const shell = (heading, bodyHtml, ctaLabel, ctaHref, footNote) => `
<div style="margin:0;padding:24px 12px;background:#faf7f5;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
  <div style="max-width:560px;margin:0 auto;background:#ffffff;border-radius:14px;padding:32px 28px;border:1px solid #f0e6e2;">
    <div style="font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:${brand};font-weight:600;">Amantrika</div>
    <h1 style="margin:14px 0 18px;font-size:22px;line-height:1.32;color:#1f1a19;font-weight:600;">${heading}</h1>
    <div style="font-size:15px;line-height:1.65;color:#453c3a;">${bodyHtml}</div>
    ${ctaHref ? `<div style="margin:26px 0 6px;"><a href="${ctaHref}" style="display:inline-block;background:${brand};color:#ffffff;text-decoration:none;padding:13px 26px;border-radius:9px;font-weight:600;font-size:15px;">${ctaLabel}</a></div>` : ''}
    ${footNote ? `<p style="margin:24px 0 0;font-size:13px;line-height:1.6;color:#8a7d7a;">${footNote}</p>` : ''}
  </div>
  <div style="max-width:560px;margin:16px auto 0;text-align:center;font-size:12px;color:#a29793;">
    Amantrika · digital invitations for Indian celebrations<br/>
    <a href="${site}" style="color:#a29793;">${site.replace(/^https?:\/\//, '')}</a>
  </div>
</div>`;
// No /unsubscribe route exists in the app yet, so RFC 8058's mailto form is
// used. See "Follow-ups" in n8n/README.md.
const unsub = (scope) => 'mailto:' + ($env.AMANTRIKA_UNSUBSCRIBE_MAILBOX || 'unsubscribe@amantrika.com')
  + '?subject=' + encodeURIComponent('unsubscribe ' + scope);
const d = $json;

const cta = site + '/admin/partners';
const bodyHtml = `
  <p style="margin:0 0 14px;"><strong>${esc(d.applicant)}</strong> applied to become a partner on ${esc(d.applied_ist)} IST.</p>
  <ul style="margin:0 0 14px;padding-left:18px;">
    <li>${esc(d.email_masked || 'no email on file')}</li>
    ${d.agency_name ? '<li>Agency: ' + esc(d.agency_name) + '</li>' : ''}
    <li>Referral code: <code>${esc(d.referral_code)}</code></li>
    <li>Commission rate: ${esc(d.commission_rate)}</li>
    <li>Invitations already built: ${d.events_built}</li>
  </ul>
  ${d.application_note
    ? '<div style="background:#faf7f5;border-radius:8px;padding:14px 16px;font-style:italic;color:#453c3a;">' + esc(d.application_note) + '</div>'
    : ''}`;

return { json: {
  dedupe_key: d.dedupe_key,
  to: '',
  stored: {
    agent_id: d.agent_id,
    applicant: d.applicant,
    agency_name: d.agency_name,
    referral_code: d.referral_code,
    dedupe_key: d.dedupe_key,
    subject: 'Partner application: ' + d.applicant + (d.agency_name ? ' (' + d.agency_name + ')' : ''),
    whatsapp: 'Partner application \u2014 ' + d.applicant
      + (d.agency_name ? ' of ' + d.agency_name : '') + ', code ' + d.referral_code
      + ', ' + d.events_built + ' invites built. Review: ' + cta,
    html: shell('New partner application', bodyHtml, 'Review at /admin/partners', cta,
      'Approving activates the referral code. Nothing is sent to the applicant automatically \u2014 a partner approval email is a follow-up (see n8n/README.md).'),
    text: 'Partner application: ' + d.applicant + '\nAgency: ' + (d.agency_name || '\u2014')
      + '\nCode: ' + d.referral_code + '\n' + cta,
  },
} };

